begin;
do $$
declare o uuid;x uuid;c uuid;p uuid;j uuid;j2 uuid;city uuid;m uuid;device text:=repeat('c',64);result jsonb;
begin
 select id into city from public.cities limit 1;
 insert into public.users(clerk_user_id,role) values('report-owner','owner') returning id into o;
 insert into public.users(clerk_user_id,role) values('report-other','owner') returning id into x;
 insert into public.users(clerk_user_id,role) values('report-cleaner','cleaner') returning id into c;
 update public.users set onboarding_completed_at=now() where id in (o,x,c);
 insert into public.properties(city_id,name,address) values(city,'Report test','Test only') returning id into p;
 insert into public.property_owners values(p,o);
 perform public.bloom_push_device(device,o,'session','challenge',jsonb_build_object('subscription',gen_random_uuid(),'hash',repeat('a',64)));
 perform public.bloom_push_device(device,o,'session','verify',jsonb_build_object('hash',repeat('a',64)));
 perform public.bloom_push_device(device,x,'session2','status');
 update private.push_control set activated_at=now();
 insert into public.jobs(property_id,checkout_date,start_at,end_at,timezone_snapshot,solo_rate_cents_snapshot) values(p,current_date,(current_date+time '11:00') at time zone 'America/Detroit',(current_date+time '15:00') at time zone 'America/Detroit','America/Detroit',7500) returning id into j;
 insert into public.job_supply_reports values(j,gen_random_uuid(),'Soap','moderate',c,now()),(j,gen_random_uuid(),'Paper','full',c,now()),(j,gen_random_uuid(),'Missing','not_found',c,now());
 insert into public.job_maintenance_reports values(j,'water','ok','',c,now()),(j,'tv','not_applicable','',c,now());
 update public.jobs set status='completed',completed_at=now(),completed_by=c where id=j;
 if exists(select 1 from private.property_report_alerts where job_id=j) then raise exception 'Normal levels produced alerts';end if;
 insert into public.jobs(property_id,checkout_date,start_at,end_at,timezone_snapshot,solo_rate_cents_snapshot) values(p,current_date+1,(current_date+1+time '11:00') at time zone 'America/Detroit',(current_date+1+time '15:00') at time zone 'America/Detroit','America/Detroit',7500) returning id into j2;
 insert into public.job_supply_reports values(j2,gen_random_uuid(),'Soap','low',c,now()),(j2,gen_random_uuid(),'Paper','empty',c,now()),(j2,gen_random_uuid(),'Towels','moderate',c,now());
 insert into public.job_maintenance_reports values(j2,'water','attention','Leak',c,now()),(j2,'wifi','ok','',c,now());
 update public.jobs set status='completed',completed_at=now(),completed_by=c where id=j2;
 update public.jobs set status=status where id=j2;
 if (select count(*) from private.property_report_alerts where job_id=j2)<>2 then raise exception 'Grouping or dedup failed';end if;
 if (select count(*) from private.push_messages where job_ids=array[j2] and kind in ('low_supplies','maintenance'))<>2 then raise exception 'Owner scope or grouping failed';end if;
 select id into m from private.push_messages where job_ids=array[j2] and kind='low_supplies' and user_id=o;
 result:=private.push_content(m,now());
 if result->>'body' not like '%Paper, Soap%' or result->>'body' like '%Towels%' then raise exception 'Low-only copy failed: %',result;end if;
 perform public.bloom_push_tick();
 if (select count(*) from private.push_deliveries d join private.push_messages msg on msg.id=d.message_id where msg.job_ids=array[j2] and msg.kind in ('low_supplies','maintenance'))<>2 then raise exception 'Delivery queue failed';end if;
 perform public.bloom_push_device(device,o,'session','preferences','{"newJobs":false,"reminders":false,"lowSupplies":false,"maintenance":false}');
 if private.push_content(m,now()) is not null then raise exception 'Opt out ignored';end if;
 perform set_config('request.jwt.claims','{"sub":"report-owner","role":"authenticated"}',true);
 if (select count(*) from private.inbox_items() i where i.id in ('low_supplies:'||j2,'maintenance:'||j2))<>2 then raise exception 'Inbox alerts missing';end if;
 perform public.bloom_notification_dismiss('low_supplies:'||j2);
 if exists(select 1 from jsonb_array_elements(public.bloom_notification_inbox()->'items') i where i->>'id'='low_supplies:'||j2) then raise exception 'Dismiss failed';end if;
 perform set_config('request.jwt.claims','{"sub":"report-other","role":"authenticated"}',true);
 if exists(select 1 from private.inbox_items() i where i.id in ('low_supplies:'||j2,'maintenance:'||j2)) then raise exception 'Owner isolation failed';end if;
 delete from public.property_owners where property_id=p and owner_id=o;
 perform public.bloom_push_device(device,o,'session','preferences','{"newJobs":false,"reminders":false,"lowSupplies":true}');
 if private.push_content(m,now()) is not null then raise exception 'Removed owner retains push access';end if;
end $$;
rollback;
